-- Türkiye ve KKTC yerleşim yerleri ve posta kodları · 14.11.2026
-- Kaynaklar: T.C. İçişleri Bakanlığı, Mülki İdare Bölümleri Envanteri (e-icisleri.gov.tr) — mahalle, köy, bağlı listeleri; PTT posta kodu sorgulama (ptt.gov.tr/posta-kodu) — güncel posta kodları; PTT posta kodu listesi 12.05.2021 — semt / bucak / belde ve yedek posta kodu; PTT listesinin 31.03.2024 türevi (MIT) — yedek posta kodu; KKTC Posta Dairesi, Uluslararası Posta Kodları (13.05.2019); Vikipedi, KKTC'deki yerleşim yerleri listesi — eski adlar
SET NAMES utf8mb4;

DROP TABLE IF EXISTS yerlesimler;
DROP TABLE IF EXISTS ilceler;
DROP TABLE IF EXISTS iller;

CREATE TABLE iller (
  id SMALLINT UNSIGNED PRIMARY KEY,
  ulke CHAR(4) NOT NULL COMMENT 'TR | KKTC',
  plaka CHAR(2) NULL COMMENT 'il plaka kodu',
  ad VARCHAR(60) NOT NULL,
  UNIQUE KEY uk_iller (ulke, ad)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

CREATE TABLE ilceler (
  id SMALLINT UNSIGNED PRIMARY KEY,
  il_id SMALLINT UNSIGNED NOT NULL,
  ad VARCHAR(80) NOT NULL,
  UNIQUE KEY uk_ilceler (il_id, ad),
  CONSTRAINT fk_ilce_il FOREIGN KEY (il_id) REFERENCES iller (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

CREATE TABLE yerlesimler (
  id INT UNSIGNED PRIMARY KEY,
  ilce_id SMALLINT UNSIGNED NOT NULL,
  semt VARCHAR(80) NULL,
  belde VARCHAR(80) NULL,
  tur ENUM('mahalle','köy','köy mahallesi','bağlı') NOT NULL,
  ad VARCHAR(120) NOT NULL,
  koy VARCHAR(120) NULL,
  posta_kodu CHAR(5) NULL,
  diger_posta_kodlari VARCHAR(120) NULL,
  eski_ad VARCHAR(120) NULL,
  kaynak VARCHAR(80) NOT NULL,
  KEY ix_ilce_ad (ilce_id, ad),
  KEY ix_posta_kodu (posta_kodu),
  CONSTRAINT fk_yerlesim_ilce FOREIGN KEY (ilce_id) REFERENCES ilceler (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;



